head.script:
// https://inswave01.atlassian.net/browse/WAEA-1058



// 테스트 설명, 유효성 값 설정
//  - description : @description 첫 문장만.
//  - @description 의 | 추가문(tooltipDisplay=true 일때 동작, 연관 속성에 의해 미표시 가능) 은 validation 으로 분리.
//  - @propval <true> 및 그 | (tooltipHideInputType=image 면 미표시), <false (default)> 는 각각 반영(default 는 2분리).
//  - @spec1(이미지 미표시 셀은 툴팁 미표시) 반영.
//  - @spec2(우선순위 체인) : image 직접 관련(tooltipHideInputType)만 포함, 일반 체인
//    (tooltipDisplayColumn / tooltipShowAlwaysColumns / secret,custom,spinner)은 타 속성 자체 동작이라 제외.
scwin.tData = {
    "description" : "[gridView > P > showImageTooltip]<br/>inputType='image' 인 Body Cell 에 마우스 오버 시 이미지 경로를 툴팁으로 표시할지 설정합니다.",
    "validation" : [
        "tooltipDisplay=true 일때 동작하며, 연관 속성에 의해 툴팁이 표시되지 않을 수 있습니다.",
        "true 설정 시, inputType='image' 인 Body Cell 에 마우스 오버 시 이미지 경로를 툴팁으로 표시합니다.",
        "true 설정 시, tooltipHideInputType 속성에 'image' 가 설정되어 있으면 툴팁이 표시되지 않습니다.",
        "false 설정 시, inputType='image' 인 Body Cell 은 툴팁을 표시하지 않습니다.",
        "미설정 시, inputType='image' 인 Body Cell 은 툴팁을 표시하지 않습니다.",
        "Body Cell 에 적용되며 이미지가 표시되지 않는 경우에는 툴팁이 표시되지 않습니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출 (gdl_boolean 등)
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 미적용 -> 기본값 명시 설정
    //  - con_showImageTooltip : gdl_boolean 바인딩(코드값 미설정='1'/true='2'/false='3').
    //    showImageTooltip 기본값 false -> 코드 '3' 으로 시작(기본 동작 = 미표시 부터 확인).
    //  - con_tooltipHideInputType : 자체 값 select1. 미설정('') 으로 시작(true 전환 시 image 툴팁이 억제되지 않도록).
    con_showImageTooltip.setValue("3");
    con_tooltipHideInputType.setSelectedIndex(0);

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - showImageTooltip / tooltipHideInputType 은 렌더 시 결정되는 속성이므로 con 변경 후
//    "Target 재생성"(btn_createTarget -> comp_init) 으로만 반영한다.
//  - 고정 전제 : tooltipDisplay="true" (showImageTooltip 은 tooltipDisplay=true 일때만 의미가 있다)
//  - Body 컬럼 구성 :
//      col_name    : text      (행 식별용, 대비군)
//      col_img     : image     (이미지 경로 값 존재) -> showImageTooltip=true 시 마우스오버 툴팁 = 이미지 경로
//      col_noimg   : image     (값/imageSrc 미설정 -> 이미지 미표시) -> @spec1 : 이미지 미표시 셀은 툴팁 미표시
//      col_textimg : textImage (imageSrc 아이콘 + 셀 텍스트를 한 셀에 함께 표시 - 이미지+텍스트 동시 표시 정식 방식)
//        · image 셀은 값=src 라 텍스트를 못 담으므로, 이미지+텍스트 공존은 inputType="textImage"(imageSrc=아이콘 경로,
//          value=텍스트) 로 구성한다. textImage 툴팁은 showImageTooltip 과 무관(엔진상 항상 tooltipDisplay 대상)하며
//          잘림 시 '텍스트'가 표시된다. imageSrc 는 유효 경로, value 는 텍스트라 404(콘솔에러) 가 발생하지 않는다.
scwin.comp_init = async function () {
    // con 선택값
    let vShow = con_showImageTooltip.getText();        // '' / 'true' / 'false'  (gdl_boolean 라벨)
    let vHide = con_tooltipHideInputType.getValue();   // '' / 'image'

    // 동적 생성용 네임스페이스 (페이지 scope 에서 공통 strNameSpace 가 비어있을 수 있어 로컬 정의)
    let ns = 'xmlns="http://www.w3.org/1999/xhtml" xmlns:ev="http://www.w3.org/2001/xml-events" xmlns:w2="http://www.inswave.com/websquare" xmlns:xf="http://www.w3.org/2002/xforms"';

    // 기존 target / dataList 정리
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 (가장 먼저 생성)
    let showMsg = (vShow === '') ? "미설정(기본 false)" : vShow;
    let hideMsg = (vHide === '') ? "미설정" : vHide;
    $c.gcm.createLabel('label="[전제] tooltipDisplay=true 고정. showImageTooltip=(' + showMsg + '), tooltipHideInputType=(' + hideMsg + ').\n[전제] image 컬럼 2개 : (이미지있음)=이미지 경로 값 존재 / (이미지없음)=값과 imageSrc 미설정으로 이미지 미표시.\n[전제] textImage 컬럼 1개 : 아이콘(imageSrc)+텍스트(value) 를 한 셀에 함께 표시 (이미지+텍스트 동시 표시 정식 방식).\n[절차] image Body Cell 에 마우스를 오버해 툴팁(이미지 경로) 표시 여부를 확인하고, 그 셀을 클릭하면 하단 반환값 영역에 현재 툴팁 정보가 출력됩니다.\n[확인] true: (이미지있음) 셀은 이미지 경로 툴팁 표시. tooltipHideInputType=image 면 미표시. (이미지없음) 셀은 미표시. false/미설정: 모든 image 셀 미표시.\n[참고] textImage 셀 툴팁은 showImageTooltip 과 무관하며 잘림 시 텍스트가 표시됩니다."', '', 'label1');

    // === 바인딩 DataList(dlt_bind) ===
    let dlt = '<w2:dataList ' + ns + ' baseNode="list" id="dlt_bind" repeatNode="map">';
    dlt += '<w2:columnInfo>';
    dlt += '<w2:column dataType="text" id="col_name" name="col_name"></w2:column>';
    dlt += '<w2:column dataType="text" id="col_img" name="col_img"></w2:column>';
    dlt += '<w2:column dataType="text" id="col_noimg" name="col_noimg"></w2:column>';
    dlt += '<w2:column dataType="text" id="col_textimg" name="col_textimg"></w2:column>';
    dlt += '</w2:columnInfo>';
    dlt += '<w2:data use="true"></w2:data>';
    dlt += '</w2:dataList>';
    $p.data.create(dlt);
    let arrDC = $p.data.getAllDataCollection("object");
    scwin.dlt_bind = arrDC[arrDC.length - 1];
    // col_img : image 셀의 값 = 이미지 경로(절대경로). col_noimg : 빈 값 -> 이미지 미표시(@spec1)
    scwin.dlt_bind.setJSON([
        { "col_name": "행 0", "col_img": "/cm/images/base/ico_grid_add.svg", "col_noimg": "", "col_textimg": "승인완료 처리된 항목입니다" },
        { "col_name": "행 1", "col_img": "/cm/images/base/ico_grid_del.svg", "col_noimg": "", "col_textimg": "반려 대기 상태인 항목입니다" }
    ], false);

    // showImageTooltip / tooltipHideInputType : con 값에 따라 설정/미설정(미설정 시 속성 제외 -> 기본값 동작 확인)
    let showAttr = (vShow === '') ? "" : 'showImageTooltip="' + vShow + '" ';
    let hideAttr = (vHide === '') ? "" : 'tooltipHideInputType="' + vHide + '" ';

    // 커스텀 GridView 인라인 정의 (tooltipDisplay=true 고정)
    let s = '<w2:gridView ' + ns + ' tooltipDisplay="true" ' + showAttr + hideAttr + 'dataList="data:dlt_bind" checkAllType="false" id="" style="width:680px;height:180px;">';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="hrow1">';
    s += '<w2:column width="80" inputType="text" id="col_name" value="행"></w2:column>';
    s += '<w2:column width="180" inputType="text" id="col_img" value="이미지있음 (image)"></w2:column>';
    s += '<w2:column width="180" inputType="text" id="col_noimg" value="이미지없음 (image)"></w2:column>';
    s += '<w2:column width="160" inputType="text" id="col_textimg" value="이미지+텍스트 (textImage)"></w2:column>';
    s += '</w2:row>';
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="brow1">';
    s += '<w2:column width="80" inputType="text" id="col_name" dataList="col_name"></w2:column>';
    s += '<w2:column width="180" inputType="image" id="col_img" dataList="col_img"></w2:column>';
    s += '<w2:column width="180" inputType="image" id="col_noimg" dataList="col_noimg"></w2:column>';
    s += '<w2:column width="160" inputType="textImage" viewType="icon" imageSrc="/cm/images/base/ico_grid_add.svg" id="col_textimg" dataList="col_textimg"></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';

    let grp_comp = $c.gcm.getTestGroup();
    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);

    // 마우스오버로 툴팁이 표시된 셀을 클릭하면 현재 표시된 툴팁 정보를 return 영역에 출력
    scwin.attachTooltipClick();
}



// 표시된 툴팁 정보를 return 영역에 출력 (마우스오버 후 그 셀 클릭 시)
//  - 엔진은 셀 클릭의 기본/버블 처리 단계에서 hover 툴팁을 닫으므로(display:none) 클릭의
//    캡처(capture) 단계 리스너로 잡아야 툴팁이 아직 살아있어 정상 출력된다.
//  - 툴팁 텍스트 확인은 공통 함수 $c.gcm.getTooltipInfo 사용(잔존 풍선 오염 방지).
scwin.attachTooltipClick = function () {
    let gridEl = scwin.target1.getElement ? scwin.target1.getElement() : document.getElementById(scwin.target1.getID());
    if (!gridEl) { return; }
    if (scwin.tooltipClickFn && scwin.tooltipClickEl) {
        scwin.tooltipClickEl.removeEventListener("click", scwin.tooltipClickFn, true);
    }
    scwin.tooltipClickFn = function () { $c.gcm.getTooltipInfo(wf_body_bottom); };
    scwin.tooltipClickEl = gridEl;
    gridEl.addEventListener("click", scwin.tooltipClickFn, true);
};
